\title{The Differential Algebra of EML Ordinary Differential Equations:\\
Logarithmic Derivatives, Galois Torsors, and a Sharp Kovacic Parity Decision}
\author{Aristotle}
\date{2026-06-28}

\begin{document}
\maketitle

\begin{abstract}
We develop, in a fully abstract differential-field setting, the algebraic core of
ordinary differential equations whose coefficients are \emph{exponential,
multiplicative, and logarithmic} (EML) functions, and apply it to the decision
problem of elementary solvability. Over an arbitrary differential field $K$ with
derivation $y \mapsto y'$ we establish four interlocking layers of structure.
First, the \emph{logarithmic derivative} $L(y) = y'/y$ is a homomorphism from the
multiplicative group $K^\times$ to the additive group $(K,+)$, whence solutions of
first-order linear equations $y' = a\,y$ multiply by adding coefficients; we prove
the finite superposition law $\big(\prod_i y_i\big)' = \big(\sum_i a_i\big)\prod_i
y_i$. Second, the \emph{constants} $\{x : x' = 0\}$ form a subfield, and the
solution space of $y' = a\,y$ is a torsor under the multiplicative group of
nonzero constants $\Gm(\CK)$. Third, the \emph{Wronskian} $W(y_1,y_2) = y_1 y_2' -
y_2 y_1'$ is constant on solutions of $y'' = a\,y$ (abstract Abel identity) and is a
sharp detector of linear independence over the constants. Fourth, the
\emph{Riccati transform} $v = y'/y$ converts $y'' = a\,y$ into $v' + v^2 = a$,
driving the first step of the Kovacic algorithm; we prove that for any polynomial
$f$ of odd degree, $v' + v^2 = f$ has no rational solution, so the generalized
Airy family $y'' = x^{2k+1} y$ --- and Airy's equation $y'' = xy$ in particular ---
has no rational Riccati solution and hence no elementary solution. Finally, the
decision is \emph{sharp}: $f = x^2 + 1$ admits the rational Riccati solution $v =
x$ (the logarithmic derivative of $e^{x^2/2}$), so the odd-degree hypothesis cannot
be weakened. All results have been formalized and machine-checked.
\end{abstract}

\section{Introduction}

Airy's equation $y'' = x\,y$, introduced by G.~B.~Airy in his 1838 study of optical
caustics, is the prototypical second-order linear ordinary differential equation
with no closed-form elementary solution. Its solutions, the Airy functions
$\mathrm{Ai}$ and $\mathrm{Bi}$, are genuinely transcendental. The modern
explanation of such impossibility is \emph{differential Galois theory}
(Picard--Vessiot theory): a linear ODE is solvable in Liouvillian (elementary)
terms if and only if its differential Galois group is suitably structured, and the
\emph{Kovacic algorithm} turns this into an effective decision procedure for
second-order equations.

This paper isolates and formalizes the algebraic engine of the EML theory in a way
independent of any characteristic, algebraic-closure, or analytic hypothesis. We
work in an arbitrary differential field $(K,{}')$ and recover the first-order
solution calculus, the constants-subfield symmetry theory, the Wronskian
independence criterion, and the Riccati transform; over $\RR[X]$ we run a
degree-parity argument that decides solvability for the generalized Airy family.

\paragraph{Contributions.}
(1) The logarithmic-derivative homomorphism (\S\ref{sec:logderiv});
(2) first-order differential Galois structure: the constants subfield and the
$\Gm(\CK)$ torsor (\S\ref{sec:galois});
(3) Wronskian theory for $y'' = a\,y$ (\S\ref{sec:wronskian});
(4) the Riccati transform and the Kovacic reduction (\S\ref{sec:riccati});
(5) a sharp parity decision for the (generalized) Airy family
(\S\ref{sec:parity}).

\section{Preliminaries: differential fields}

\begin{definition}[Differential field]
A \emph{differential field} is a field $K$ together with an additive map
$\,' : K \to K$ (the \emph{derivation}) satisfying the Leibniz rule
$(xy)' = x'y + x y'$. One derives the quotient rule
$(y/z)' = (y'z - yz')/z^2$ and the inverse rule $(y^{-1})' = -y'/y^2$ for $z, y
\neq 0$.
\end{definition}

\begin{definition}[Constants]
The \emph{field of constants} of $K$ is $\CK = \{\, x \in K : x' = 0 \,\}$.
\end{definition}

\begin{definition}[Logarithmic derivative]
For $y \neq 0$, the \emph{logarithmic derivative} is $\Ldop(y) = y'/y$.
\end{definition}

\section{The logarithmic derivative as an EML homomorphism}
\label{sec:logderiv}

\begin{theorem}[Homomorphism law, \texttt{logDeriv\_mul}]
For nonzero $y, z \in K$,
\[ \Ldop(yz) = \frac{(yz)'}{yz} = \frac{y'}{y} + \frac{z'}{z} = \Ldop(y) + \Ldop(z). \]
\end{theorem}
\begin{proof}[Proof sketch]
Expand $(yz)' = y'z + yz'$ by Leibniz, divide by $yz$, and simplify.
\end{proof}

\begin{corollary}[Quotient, inverse, power laws]
For nonzero $y, z$ and $n \in \ZZ$:
\[ \Ldop(y/z) = \Ldop(y) - \Ldop(z), \quad \Ldop(y^{-1}) = -\Ldop(y), \quad
   \Ldop(y^n) = n\,\Ldop(y). \]
(\texttt{logDeriv\_div}, \texttt{logDeriv\_inv}, \texttt{logDeriv\_zpow}; the power
law by integer induction.)
\end{corollary}

The equation $y' = a\,y$ is equivalent to $\Ldop(y) = a$ for $y \neq 0$, so its
solution set is the $\Ldop$-fibre over $a$, a coset of $\ker \Ldop = \CK$.

\begin{theorem}[Binary superposition, \texttt{firstOrder\_mul}]
If $y' = a\,y$ and $z' = b\,z$, then $(yz)' = (a+b)(yz)$.
\end{theorem}
\begin{proof}[Proof sketch]
$(yz)' = y'z + yz' = ayz + byz = (a+b)yz$.
\end{proof}

\begin{theorem}[Inverse, quotient, power solutions]
If $y' = a\,y$ (and where needed $y \neq 0$):
$(y^{-1})' = (-a) y^{-1}$;
$(y/z)' = (a-b)(y/z)$ when $z' = bz$, $z \neq 0$;
$(y^n)' = (na) y^n$ for $n \in \ZZ$.
(\texttt{firstOrder\_inv}, \texttt{firstOrder\_div}, \texttt{firstOrder\_zpow}.)
\end{theorem}

\begin{theorem}[Finite superposition, \texttt{firstOrder\_prod}]
For a finite family $(y_i)_{i \in s}$ with $y_i' = a_i y_i$ for all $i \in s$,
\[ \Big(\prod_{i \in s} y_i\Big)' = \Big(\sum_{i \in s} a_i\Big)\,\prod_{i \in s} y_i. \]
\end{theorem}
\begin{proof}[Proof sketch]
Finite-set induction. The empty product gives $1' = 0$ (the honest zero-coefficient
base case). The inductive step applies Leibniz to $y_j \cdot \prod_{i \in s} y_i$,
uses the inductive hypothesis and $y_j' = a_j y_j$, and finishes with ring
normalization.
\end{proof}

This is the abstract content of $\prod_i e^{\int a_i} = e^{\sum_i \int a_i}$.

\section{Differential Galois structure of first-order EML equations}
\label{sec:galois}

\begin{theorem}[Constants form a subfield, \texttt{constantsSubfield}]
$\CK = \{x : x' = 0\}$ is a subfield of $K$.
\end{theorem}
\begin{proof}[Proof sketch]
Closure under $+,-$ is additivity; under $\times$ is Leibniz; under inversion is the
inverse rule.
\end{proof}

\begin{theorem}[Solution ratio is constant,
\texttt{solution\_ratio\_isConstant}]
If $y_1' = a y_1$, $y_2' = a y_2$ and $y_1 \neq 0$, then $(y_2/y_1)' = 0$.
\end{theorem}
\begin{proof}[Proof sketch]
$\Ldop(y_2/y_1) = \Ldop(y_2) - \Ldop(y_1) = a - a = 0$; clear denominators.
\end{proof}

\begin{theorem}[Galois action by multiplicative constants,
\texttt{galois\_action\_is\_mul\_constant}]
If $y_1, y_2$ are nonzero solutions of $y' = a\,y$, there is a nonzero constant $c$
with $c' = 0$ and $y_2 = c\,y_1$.
\end{theorem}
\begin{proof}[Proof sketch]
Take $c = y_2/y_1$: nonzero, constant by the previous theorem, with $y_2 = c y_1$.
\end{proof}

\begin{theorem}[Closure under constant scaling, \texttt{const\_mul\_solution}]
If $c' = 0$ and $y' = a\,y$, then $(cy)' = a(cy)$.
\end{theorem}

\begin{theorem}[Torsor structure, \texttt{galois\_torsor}]
Fix a nonzero solution $y_1$ of $y' = a\,y$. For any $y_2 \in K$,
\[ \big(y_2' = a y_2 \wedge y_2 \neq 0\big) \iff
   \exists c \neq 0,\ c' = 0,\ y_2 = c\,y_1. \]
\end{theorem}

The solution space is one-dimensional over the constants and the Galois group acts
by $\Gm(\CK)$ --- the simplest linear-algebraic (``EML'') group.

\section{Wronskian theory for second-order EML equations}
\label{sec:wronskian}

\begin{definition}[Wronskian]
$W(y_1, y_2) = y_1 y_2' - y_2 y_1'$.
\end{definition}

\begin{theorem}[Abstract Abel identity, \texttt{wronskian\_deriv\_eq\_zero},
\texttt{wronskian\_isConstant}]
If $y_1'' = a y_1$ and $y_2'' = a y_2$, then $W(y_1,y_2)' = 0$, i.e.\ $W(y_1,y_2)
\in \CK$.
\end{theorem}
\begin{proof}[Proof sketch]
$W' = y_1 y_2'' - y_2 y_1'' = y_1(a y_2) - y_2(a y_1) = 0$.
\end{proof}

\begin{definition}[Linear dependence over constants,
\texttt{LinDepOverConstants}]
$(y_1, y_2)$ is \emph{linearly dependent over the constants} if there exist $c_1,
c_2 \in \CK$, not both zero, with $c_1 y_1 + c_2 y_2 = 0$.
\end{definition}

\begin{theorem}[Dependence forces $W = 0$,
\texttt{wronskian\_eq\_zero\_of\_linDep}]
If $(y_1,y_2)$ is linearly dependent over the constants, then $W(y_1,y_2) = 0$.
\end{theorem}
\begin{proof}[Proof sketch]
Differentiating $c_1 y_1 + c_2 y_2 = 0$ (constants drop out) gives $c_1 y_1' + c_2
y_2' = 0$. Eliminating $y_2$ and $y_1$ yields $c_1 W = 0$ and $c_2 W = 0$; since
$(c_1,c_2) \neq (0,0)$, $W = 0$.
\end{proof}

\begin{corollary}[Independence criterion,
\texttt{linIndep\_of\_wronskian\_ne\_zero}]
If $W(y_1,y_2) \neq 0$ then $(y_1,y_2)$ is linearly independent over the constants.
\end{corollary}

\begin{theorem}[Fundamental-system criterion,
\texttt{wronskian\_isConstant\_ne\_zero\_of\_linIndep}]
If $y_1, y_2$ solve $y'' = a\,y$ and $W(y_1,y_2) \neq 0$, then $W(y_1,y_2)$ is a
nonzero constant.
\end{theorem}

Also recorded: \texttt{scale\_solution}, \texttt{add\_solution} (solutions form a
$\CK$-module), and \texttt{wronskian\_dependent\_eq\_zero}.

\section{The Riccati transform and the Kovacic reduction}
\label{sec:riccati}

\begin{theorem}[Riccati transform, raw form, \texttt{logDeriv\_riccati}]
For $y \neq 0$, $\Ldop(y)' + \Ldop(y)^2 = y''/y$.
\end{theorem}
\begin{proof}[Proof sketch]
$\Ldop(y)' = y''/y - (y'/y)^2 = y''/y - \Ldop(y)^2$; rearrange.
\end{proof}

\begin{theorem}[Riccati from second order, \texttt{riccati\_of\_second\_order}]
If $y \neq 0$ solves $y'' = a\,y$, then $v = \Ldop(y)$ solves $v' + v^2 = a$.
\end{theorem}

A rational candidate $v = p/q$ with $p, q \in \RR[X]$, $q \neq 0$, satisfies $v' +
v^2 = f$ iff the polynomial identity
\begin{equation}
  p'\,q - p\,q' + p^2 = f\,q^2 \tag{$\ast$}\label{eq:cleared}
\end{equation}
holds, obtained by clearing denominators.

\section{A sharp degree-parity decision for the Airy family}
\label{sec:parity}

\begin{lemma}[\texttt{natDegree\_wronskianLike\_le}]
For $p, q \in \RR[X]$, $\deg(p'q - pq') \le \deg p + \deg q - 1$.
\end{lemma}

\begin{theorem}[Odd-degree Riccati obstruction,
\texttt{no\_rational\_solves\_riccati\_odd\_deg}]
Let $f \in \RR[X]$ have odd degree. Then no $p, q \in \RR[X]$ with $q \neq 0$
satisfy \eqref{eq:cleared}; equivalently $v' + v^2 = f$ has no rational solution.
\end{theorem}
\begin{proof}[Proof sketch]
The right side $f q^2$ has degree $\deg f + 2\deg q$, odd. The left side: $p'q -
pq'$ has degree $\le \deg p + \deg q - 1$ (Lemma), and $p^2$ has even degree $2\deg
p$. If $\deg p \ge \deg q$, the left side has degree exactly $2\deg p$ (even),
contradicting odd $\deg f + 2\deg q$. If $\deg p < \deg q$, the left side has degree
$\le 2\deg q - 2 < 2\deg q + 1 \le \deg f + 2\deg q$. Either way \eqref{eq:cleared}
fails. Coprimality is not used.
\end{proof}

\begin{theorem}[Airy, \texttt{no\_rational\_solves\_riccati\_airy}]
$v' + v^2 = x$ has no rational solution.
\end{theorem}
\begin{proof}
Apply the previous theorem with $f = X$, $\deg X = 1$ odd.
\end{proof}

\begin{theorem}[Generalized Airy, \texttt{no\_rational\_riccati\_genAiry}]
For every $k \in \NN$, $y'' = x^{2k+1} y$ has no rational Riccati solution. Airy is
$k = 0$.
\end{theorem}

We also record the polynomial obstructions: no nonzero polynomial solves $y'' =
xy$ (\texttt{no\_poly\_solves\_airy}), generalizing to positive-degree coefficients
(\texttt{no\_poly\_solves\_second\_order\_pos\_deg}) and to $y'' = x^n y$
(\texttt{no\_poly\_solves\_gen\_airy}).

\begin{theorem}[Even-degree solvability witness,
\texttt{riccati\_evenDeg\_solvable}]
$v' + v^2 = x^2 + 1$ has the polynomial solution $v = x$: with $p = X$, $q = 1$,
\eqref{eq:cleared} reads $1 + X^2 = X^2 + 1$.
\end{theorem}
\begin{remark}
$v = x$ is the logarithmic derivative of $y = e^{x^2/2}$, which solves $y'' =
(x^2+1)y$; the equation is genuinely EML-solvable. The coefficient has even degree
$2$ (\texttt{natDegree\_evenWitness}).
\end{remark}

\begin{theorem}[Sharp parity decision,
\texttt{kovacic\_parity\_decision\_sharp}]
\[ \Big(\forall k \in \NN,\ v' + v^2 = x^{2k+1}\ \text{has no rational solution}\Big)
   \wedge \Big(v' + v^2 = x^2 + 1\ \text{has a rational solution}\Big). \]
\end{theorem}

Hence ``$\deg f$ odd'' is a correct and tight first-step decision on the family
$y'' = f\,y$.

\section{Algorithms}

\paragraph{First-step Kovacic parity decision.}
Given $f$, compute $d = \deg f$. If $d$ is odd, return \textsc{Obstructed} (a
theorem). Otherwise the parity test is inconclusive and a bounded rational search is
invoked. The parity test is $O(1)$ after computing $\deg f$.

\paragraph{Bounded rational Riccati search.}
Search $p, q$ with $\deg p, \deg q \le N$ solving \eqref{eq:cleared}; matching
coefficients yields a finite algebraic system. The polynomial sub-case $q = 1$
reduces to solving $p' + p^2 = f$ degree-by-degree.

\section{Discussion and future work}

The non-elementary nature of $\mathrm{Ai}, \mathrm{Bi}$ is recovered as a
degree-parity theorem and extends to the generalized Airy hierarchy. Future
directions include a Riccati gauge transforming $y'' + p y' + q y = 0$ to normal
form (transporting the obstruction to e.g.\ $y'' - 2x y' + (x^2-1)y = 0$); a
concrete \texttt{Differential (RatFunc\,$\RR$)} instance whose constants are exactly
$\RR$, making the torsor result a concrete $\RR^\times$-torsor statement over
$\RR(x)$; and an effective dimension-2 theory in which every fundamental system
arises by reduction of order.

\section{Conclusion}

A single homomorphism --- the logarithmic derivative carrying products to sums ---
organizes the EML theory: first-order equations exponentiate with $\Gm(\CK)$-torsor
solution spaces; second-order equations are governed by a constant Wronskian and
reduce, via the Riccati transform, to a first-order quadratic; and the decision
problem is settled, for the generalized Airy family, by a sharp degree-parity
criterion. Airy's equation has no elementary solution because $1$ is odd --- and
$x^2+1$ shows that this parity is exactly the dividing line.

